style.css:
/* Dark Strawberry Milk */
body { background: #211517 !important; color: #F9DCE0 !important; }
h1, h2, h3 { color: #F09AAF !important; }
p { color: #D7B2B8 !important; }
a { color: #F4A6B7 !important; }
button {
  background: #853E53 !important;
  color: #FFF0F2 !important;
  border: 1px solid #C96B82 !important;
  border-radius: 12px !important;
}
input, textarea {
  background: #302025 !important;
  color: #F9DCE0 !important;
  border: 1px solid #854C5C !important;
}
::selection { background: #C96B82; color: white; }
